  [279251] = { "I colpi di Lacerazione hanno il $N1% di probabilità di azzerare il tempo di recupero di Morso Primordiale.", 0xa7fe2f7c, "u" },
  [279258] = { "Aumenta in modo permanente di $N1 la Difesa e di $N2 la Tempra di un oggetto indossato su torso, gambe, mani o piedi. Utilizzabile solo su oggetti di livello $N3 o superiore.", 0x0d8855e9, "u" },
