  [279947] = { "Colloca un Seed Hybridizer che permette di moltiplicare i semi o di combinarli in gradi più rari e fornisce tutti i benefici di un'Incense Candle. Richiede un Fuoco da Campo nelle vicinanze.\n\nPuò essere collocato sopra un'Incense Candle per sostituirla. Tutti gli elementi da campeggio condividono un tempo di recupero di $D1.", 0xa466fc3a, "u" },
